import{_ as e,o as l,c as a,a3 as n}from"./chunks/framework.bvEHUNtb.js";const h=JSON.parse('{"title":"14 二十四节气","description":"从黄道位置、物候与历法机制理解二十四节气。","frontmatter":{"title":"14 二十四节气","description":"从黄道位置、物候与历法机制理解二十四节气。","category":"guide","aliases":["二十四节气","节气"]},"headers":[],"relativePath":"topics/traditional-wisdom/time/twenty-four-solar-terms.md","filePath":"topics/traditional-wisdom/time/twenty-four-solar-terms.md","lastUpdated":1786982540000}'),s={name:"topics/traditional-wisdom/time/twenty-four-solar-terms.md"};function r(i,t,o,d,g,p){return l(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="_14-·-二十四节气-天地的时间刻度" tabindex="-1">14 · 二十四节气：天地的时间刻度 <a class="header-anchor" href="#_14-·-二十四节气-天地的时间刻度" aria-label="Permalink to &quot;14 · 二十四节气：天地的时间刻度&quot;">​</a></h1><p><strong>文档版本：v1.1 · 二十四节气 | 2026年7月 | 已按审查意见修订</strong></p><h2 id="版本与引用说明" tabindex="-1">版本与引用说明 <a class="header-anchor" href="#版本与引用说明" aria-label="Permalink to &quot;版本与引用说明&quot;">​</a></h2><p>本篇主要依据：</p><ul><li>《淮南子·天文训》（刘安等，约前139年）——现存最早完整记载二十四节气的文献</li><li>《周髀算经》（成书约前1世纪，含更早天文测算内容）——节气的天文测算依据</li><li>《礼记·月令》（先秦至汉）——节气物候的礼制化文献</li><li>《夏小正》（传夏代，今本约春秋至汉，收录于《大戴礼记》）——上古物候历，节气体系的源头</li><li>《史记·历书》（司马迁，约前91年）——历法沿革记载</li><li>《汉书·律历志》（班固，约公元80年）——节气与历法的制度化记载</li><li>《逸周书·时训解》（先秦）——七十二候的最早系统记载</li><li>考古参照：安徽阜阳汝阴侯墓出土节气盘（约前165年）——现存最早节气实物</li></ul><hr><h2 id="一、体系定位-在知识树中的坐标" tabindex="-1">一、体系定位：在知识树中的坐标 <a class="header-anchor" href="#一、体系定位-在知识树中的坐标" aria-label="Permalink to &quot;一、体系定位：在知识树中的坐标&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>太阳运行轨道（黄道）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>  二十四等分 = 二十四节气        ←── 本篇</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>  每个节气对应一个地支月的起点</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>  月建（十二地支的月份系统）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>  四柱起月柱 · 奇门起局 · 择日 · 六爻月建判断</span></span></code></pre></div><p>节气在整个体系里的位置：</p><table tabindex="0"><thead><tr><th style="text-align:left;">层级</th><th style="text-align:left;">内容</th><th style="text-align:left;">本篇关系</th></tr></thead><tbody><tr><td style="text-align:left;">天文层</td><td style="text-align:left;">太阳在黄道上的位置</td><td style="text-align:left;">节气的本质</td></tr><tr><td style="text-align:left;">历法层</td><td style="text-align:left;">阴阳合历的&quot;阳&quot;的骨架</td><td style="text-align:left;">节气是农历的太阳坐标</td></tr><tr><td style="text-align:left;">术数层</td><td style="text-align:left;">奇门·四柱·六爻的时间基准</td><td style="text-align:left;">换月以节气为准，不以朔日为准</td></tr><tr><td style="text-align:left;">文化层</td><td style="text-align:left;">农耕·饮食·诗歌·民俗</td><td style="text-align:left;">节气活在日常生活里</td></tr></tbody></table><p><strong>一句话定位：</strong></p><blockquote><p>二十四节气，是古人把太阳在黄道上运行一圈（365.25天）精确等分为二十四段的时间刻度系统。<br> 它不是&quot;农历的一部分&quot;，而是独立的太阳历坐标——<br> 是古代中国最精确、最实用、沿用至今的天文成就。</p></blockquote><hr><h2 id="二、原典依据" tabindex="-1">二、原典依据 <a class="header-anchor" href="#二、原典依据" aria-label="Permalink to &quot;二、原典依据&quot;">​</a></h2><h3 id="文献一-《淮南子·天文训》——现存最早完整记载" tabindex="-1">文献一：《淮南子·天文训》——现存最早完整记载 <a class="header-anchor" href="#文献一-《淮南子·天文训》——现存最早完整记载" aria-label="Permalink to &quot;文献一：《淮南子·天文训》——现存最早完整记载&quot;">​</a></h3><p><strong>【原典】</strong>《淮南子》卷三·天文训（刘安等，约前139年）</p><p><strong>【原文节选】</strong></p><blockquote><p>&quot;距日冬至四十六日而立春，阳气冻解，音比南吕。<br> 加十五日指寅，则雨水……<br> 加十五日指甲，则雷惊蛰……&quot;</p></blockquote><p>《天文训》以&quot;加十五日&quot;的方式，完整记载了二十四节气的名称与顺序，<br> 是目前可考的最早完整版本，证明二十四节气体系在西汉初年已完全成型。</p><h3 id="文献二-《周髀算经》——节气的天文测算依据" tabindex="-1">文献二：《周髀算经》——节气的天文测算依据 <a class="header-anchor" href="#文献二-《周髀算经》——节气的天文测算依据" aria-label="Permalink to &quot;文献二：《周髀算经》——节气的天文测算依据&quot;">​</a></h3><p><strong>【原典】</strong>《周髀算经》（成书约前1世纪，含更早内容）</p><p><strong>【原文节选】</strong></p><blockquote><p>&quot;冬至日，日出辰而入申……夏至日，日出寅而入戌……&quot;</p></blockquote><p>《周髀算经》记载了用&quot;土圭测影&quot;（立竿见影）测定冬至夏至的方法，<br> 是节气天文测算的核心依据。<br> 冬至日影最长，夏至日影最短——这是二十四节气体系的测量起点。</p><h3 id="文献三-《礼记·月令》——节气的礼制与物候制度化" tabindex="-1">文献三：《礼记·月令》——节气的礼制与物候制度化 <a class="header-anchor" href="#文献三-《礼记·月令》——节气的礼制与物候制度化" aria-label="Permalink to &quot;文献三：《礼记·月令》——节气的礼制与物候制度化&quot;">​</a></h3><p><strong>【原典】</strong>《礼记》第六篇·月令（先秦至汉）</p><p><strong>【原文节选】</strong></p><blockquote><p>&quot;孟春之月，日在营室，昏参中，旦尾中。<br> 其日甲乙，其帝太皞，其神句芒，其虫鳞，<br> 其音角，律中太蔟，其数八，其味酸，其臭膻，<br> 其祀户，祭先脾。东风解冻，蛰虫始振，鱼上冰，<br> 獭祭鱼，候雁北。&quot;</p></blockquote><p>《月令》将每月的天象、物候、政令、禁忌一一对应，<br> 是节气从天文观测走向礼制规范与生活实践的关键文献。</p><h3 id="文献四-《夏小正》——上古物候历-节气的前身" tabindex="-1">文献四：《夏小正》——上古物候历，节气的前身 <a class="header-anchor" href="#文献四-《夏小正》——上古物候历-节气的前身" aria-label="Permalink to &quot;文献四：《夏小正》——上古物候历，节气的前身&quot;">​</a></h3><p><strong>【原典】</strong>《夏小正》（传夏代，今本约春秋至汉，收录于《大戴礼记》）</p><p><strong>【原文节选】</strong></p><blockquote><p>&quot;正月：启蛰，雁北乡，雉震呴，鱼陟负冰……<br> 四月：昴则见，初昏南门正……&quot;</p></blockquote><p>《夏小正》是中国现存最早的物候历，<br> 以动植物的季节性变化来标记时间，<br> 是二十四节气&quot;物候系统&quot;的直接源头。</p><h2 id="三、来源与演变-节气从哪里来" tabindex="-1">三、来源与演变：节气从哪里来？ <a class="header-anchor" href="#三、来源与演变-节气从哪里来" aria-label="Permalink to &quot;三、来源与演变：节气从哪里来？&quot;">​</a></h2><h3 id="_3-1-最早的时间刻度-二至二分-四个核心节气" tabindex="-1">3.1 最早的时间刻度：二至二分（四个核心节气） <a class="header-anchor" href="#_3-1-最早的时间刻度-二至二分-四个核心节气" aria-label="Permalink to &quot;3.1 最早的时间刻度：二至二分（四个核心节气）&quot;">​</a></h3><p>节气体系的起点，是对太阳极值的观测：</p><table tabindex="0"><thead><tr><th style="text-align:left;">节气</th><th style="text-align:left;">天文含义</th><th style="text-align:left;">测量方法</th><th style="text-align:left;">历史地位</th></tr></thead><tbody><tr><td style="text-align:left;">冬至</td><td style="text-align:left;">北半球白昼最短，日影最长</td><td style="text-align:left;">土圭测影，影最长之日</td><td style="text-align:left;">最早被确定，是整个体系的原点</td></tr><tr><td style="text-align:left;">夏至</td><td style="text-align:left;">北半球白昼最长，日影最短</td><td style="text-align:left;">土圭测影，影最短之日</td><td style="text-align:left;">与冬至对应，确定一年周期</td></tr><tr><td style="text-align:left;">春分</td><td style="text-align:left;">昼夜等长，太阳直射赤道</td><td style="text-align:left;">观测日出正东方</td><td style="text-align:left;">农耕播种的信号</td></tr><tr><td style="text-align:left;">秋分</td><td style="text-align:left;">昼夜等长，太阳直射赤道</td><td style="text-align:left;">观测日落正西方</td><td style="text-align:left;">农耕收割的信号</td></tr></tbody></table><p><strong>考古证据：</strong></p><ul><li>河南濮阳西水坡仰韶文化遗址（约前4500年）出土的蚌塑龙虎图，方位与二至二分高度吻合，说明中国先民对四个极值节气的观测，可能早至新石器时代晚期。</li><li>山西陶寺遗址观象台（约前2000年），是迄今发现最早的土圭测影实物遗址。</li></ul><h3 id="_3-2-从四到八-加入四立" tabindex="-1">3.2 从四到八：加入四立 <a class="header-anchor" href="#_3-2-从四到八-加入四立" aria-label="Permalink to &quot;3.2 从四到八：加入四立&quot;">​</a></h3><p>在二至二分的基础上，各取中点，加入四立：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>冬至 ──── 春分 ──── 夏至 ──── 秋分 ──── 冬至</span></span>
<span class="line"><span>      ↑          ↑          ↑          ↑</span></span>
<span class="line"><span>    立春        立夏        立秋        立冬</span></span>
<span class="line"><span>（冬至↔春分  （春分↔夏至  （夏至↔秋分  （秋分↔冬至</span></span>
<span class="line"><span>  的中点）     的中点）     的中点）     的中点）</span></span></code></pre></div><p>四立标志四季的开始，二至二分标志四季的中点。<br> 这八个节气，构成了节气体系的骨架，在《左传》《国语》等先秦文献中已有记载。</p><h3 id="_3-3-从八到二十四-完整体系的形成" tabindex="-1">3.3 从八到二十四：完整体系的形成 <a class="header-anchor" href="#_3-3-从八到二十四-完整体系的形成" aria-label="Permalink to &quot;3.3 从八到二十四：完整体系的形成&quot;">​</a></h3><p>将一年进一步细分，在八个骨架节气之间，每隔约15天插入一个节气，最终形成二十四节气。</p><p><strong>完整体系的形成时间线：</strong></p><ul><li><strong>战国时期：</strong> 已有接近完整的节气记载（《吕氏春秋·十二纪》含部分节气）</li><li><strong>秦汉之际：</strong> 二十四节气完全定型</li><li><strong>西汉·前139年：</strong> 《淮南子·天文训》完整记载，是现存最早完整版本</li><li><strong>西汉·前104年：</strong> 汉武帝颁布《太初历》，二十四节气正式纳入国家历法，成为制度</li></ul><h3 id="_3-4-考古证据-节气体系的成型时间线" tabindex="-1">3.4 考古证据：节气体系的成型时间线 <a class="header-anchor" href="#_3-4-考古证据-节气体系的成型时间线" aria-label="Permalink to &quot;3.4 考古证据：节气体系的成型时间线&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">时间</th><th style="text-align:left;">证据</th><th style="text-align:left;">意义</th></tr></thead><tbody><tr><td style="text-align:left;">约前4500年</td><td style="text-align:left;">濮阳西水坡仰韶遗址蚌塑图</td><td style="text-align:left;">二至二分观测的可能源头</td></tr><tr><td style="text-align:left;">约前2000年</td><td style="text-align:left;">陶寺遗址观象台（山西襄汾）</td><td style="text-align:left;">土圭测影的实物证据，可测冬至夏至</td></tr><tr><td style="text-align:left;">约前7世纪</td><td style="text-align:left;">《诗经·豳风·七月》</td><td style="text-align:left;">物候历的文学记载</td></tr><tr><td style="text-align:left;">约前239年</td><td style="text-align:left;">《吕氏春秋·十二纪》</td><td style="text-align:left;">接近完整的节气体系</td></tr><tr><td style="text-align:left;">约前165年</td><td style="text-align:left;">安徽阜阳汝阴侯墓节气盘</td><td style="text-align:left;">现存最早节气实物，二十四节气完整刻于圆盘</td></tr><tr><td style="text-align:left;">约前139年</td><td style="text-align:left;">《淮南子·天文训》</td><td style="text-align:left;">现存最早完整文字记载</td></tr><tr><td style="text-align:left;">前104年</td><td style="text-align:left;">汉武帝《太初历》</td><td style="text-align:left;">节气正式入法，成为国家历法制度</td></tr><tr><td style="text-align:left;">2016年</td><td style="text-align:left;">UNESCO人类非物质文化遗产</td><td style="text-align:left;">现代国际认定</td></tr></tbody></table><p>part2 = &quot;&quot;&quot;</p><h2 id="四、二十四节气完整详解" tabindex="-1">四、二十四节气完整详解 <a class="header-anchor" href="#四、二十四节气完整详解" aria-label="Permalink to &quot;四、二十四节气完整详解&quot;">​</a></h2><h3 id="_4-0-七十二候-节气的最小时间单位" tabindex="-1">4.0 七十二候：节气的最小时间单位 <a class="header-anchor" href="#_4-0-七十二候-节气的最小时间单位" aria-label="Permalink to &quot;4.0 七十二候：节气的最小时间单位&quot;">​</a></h3><p>在进入逐节详解之前，先了解节气体系的最高精度版本——<strong>七十二候</strong>。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个节气 = 三候</span></span>
<span class="line"><span>一候     = 五天</span></span>
<span class="line"><span>24节气 × 3候 = 72候</span></span></code></pre></div><p><strong>三候的结构：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">候次</th><th style="text-align:left;">时间段</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;">初候</td><td style="text-align:left;">第1—5天</td><td style="text-align:left;">该节气最先出现的物候变化</td></tr><tr><td style="text-align:left;">二候</td><td style="text-align:left;">第6—10天</td><td style="text-align:left;">物候变化的深化</td></tr><tr><td style="text-align:left;">三候</td><td style="text-align:left;">第11—15天</td><td style="text-align:left;">该节气物候的完成</td></tr></tbody></table><p><strong>来源：</strong>《逸周书·时训解》（先秦），是七十二候的最早系统记载。</p><p><strong>候的内容：</strong> 以动植物的季节性行为变化为标志——候鸟的迁徙、虫鱼的出没、草木的荣枯、气象的变化，都被古人精确记录，形成一套完整的自然观察体系。</p><p><strong>意义：</strong> 七十二候是节气体系的最高精度版本，将一年细分为72个自然状态，是古人对自然观察细腻程度的极致体现，也是《夏小正》物候传统的直接延续。</p><blockquote><p>本篇每个节气的物候描述，均引自《逸周书·时训解》的三候记载。</p></blockquote><hr><h3 id="_4-1-总览表" tabindex="-1">4.1 总览表 <a class="header-anchor" href="#_4-1-总览表" aria-label="Permalink to &quot;4.1 总览表&quot;">​</a></h3><blockquote><p><strong>说明：</strong></p><ul><li>总览表从<strong>小寒</strong>起排，对应地支丑月，符合地支月序（丑→寅→卯……子）的起点逻辑</li><li>太阳黄经以<strong>春分点为0°</strong>（即360°归零处），每15°一个节气，依次递增</li><li>春分标注0°，是黄道坐标系的起算点定义；小寒285°至冬至270°为一完整循环</li><li><strong>加粗节气 = 十二&quot;节&quot;</strong>，是四柱八字换月柱、奇门换局的时间基准</li></ul></blockquote><table tabindex="0"><thead><tr><th style="text-align:center;">序号</th><th style="text-align:left;">节气</th><th style="text-align:left;">公历约日期</th><th style="text-align:center;">太阳黄经</th><th style="text-align:left;">农历月</th><th style="text-align:left;">地支月</th><th style="text-align:center;">类型</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong>小寒</strong></td><td style="text-align:left;">1月5—7日</td><td style="text-align:center;">285°</td><td style="text-align:left;">十二月</td><td style="text-align:left;">丑月起</td><td style="text-align:center;"><strong>节</strong></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;">大寒</td><td style="text-align:left;">1月20—21日</td><td style="text-align:center;">300°</td><td style="text-align:left;">十二月</td><td style="text-align:left;">丑月</td><td style="text-align:center;">气</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong>立春</strong></td><td style="text-align:left;">2月3—5日</td><td style="text-align:center;">315°</td><td style="text-align:left;">正月始</td><td style="text-align:left;">寅月起</td><td style="text-align:center;"><strong>节</strong></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;">雨水</td><td style="text-align:left;">2月18—20日</td><td style="text-align:center;">330°</td><td style="text-align:left;">正月</td><td style="text-align:left;">寅月</td><td style="text-align:center;">气</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong>惊蛰</strong></td><td style="text-align:left;">3月5—7日</td><td style="text-align:center;">345°</td><td style="text-align:left;">二月始</td><td style="text-align:left;">卯月起</td><td style="text-align:center;"><strong>节</strong></td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;">春分</td><td style="text-align:left;">3月20—21日</td><td style="text-align:center;">0°（360°）</td><td style="text-align:left;">二月</td><td style="text-align:left;">卯月</td><td style="text-align:center;">气</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong>清明</strong></td><td style="text-align:left;">4月4—6日</td><td style="text-align:center;">15°</td><td style="text-align:left;">三月始</td><td style="text-align:left;">辰月起</td><td style="text-align:center;"><strong>节</strong></td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;">谷雨</td><td style="text-align:left;">4月19—21日</td><td style="text-align:center;">30°</td><td style="text-align:left;">三月</td><td style="text-align:left;">辰月</td><td style="text-align:center;">气</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><strong>立夏</strong></td><td style="text-align:left;">5月5—7日</td><td style="text-align:center;">45°</td><td style="text-align:left;">四月始</td><td style="text-align:left;">巳月起</td><td style="text-align:center;"><strong>节</strong></td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;">小满</td><td style="text-align:left;">5月20—22日</td><td style="text-align:center;">60°</td><td style="text-align:left;">四月</td><td style="text-align:left;">巳月</td><td style="text-align:center;">气</td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;"><strong>芒种</strong></td><td style="text-align:left;">6月5—7日</td><td style="text-align:center;">75°</td><td style="text-align:left;">五月始</td><td style="text-align:left;">午月起</td><td style="text-align:center;"><strong>节</strong></td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;">夏至</td><td style="text-align:left;">6月21—22日</td><td style="text-align:center;">90°</td><td style="text-align:left;">五月</td><td style="text-align:left;">午月</td><td style="text-align:center;">气</td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;"><strong>小暑</strong></td><td style="text-align:left;">7月6—8日</td><td style="text-align:center;">105°</td><td style="text-align:left;">六月始</td><td style="text-align:left;">未月起</td><td style="text-align:center;"><strong>节</strong></td></tr><tr><td style="text-align:center;">14</td><td style="text-align:left;">大暑</td><td style="text-align:left;">7月22—24日</td><td style="text-align:center;">120°</td><td style="text-align:left;">六月</td><td style="text-align:left;">未月</td><td style="text-align:center;">气</td></tr><tr><td style="text-align:center;">15</td><td style="text-align:left;"><strong>立秋</strong></td><td style="text-align:left;">8月7—9日</td><td style="text-align:center;">135°</td><td style="text-align:left;">七月始</td><td style="text-align:left;">申月起</td><td style="text-align:center;"><strong>节</strong></td></tr><tr><td style="text-align:center;">16</td><td style="text-align:left;">处暑</td><td style="text-align:left;">8月22—24日</td><td style="text-align:center;">150°</td><td style="text-align:left;">七月</td><td style="text-align:left;">申月</td><td style="text-align:center;">气</td></tr><tr><td style="text-align:center;">17</td><td style="text-align:left;"><strong>白露</strong></td><td style="text-align:left;">9月7—9日</td><td style="text-align:center;">165°</td><td style="text-align:left;">八月始</td><td style="text-align:left;">酉月起</td><td style="text-align:center;"><strong>节</strong></td></tr><tr><td style="text-align:center;">18</td><td style="text-align:left;">秋分</td><td style="text-align:left;">9月22—24日</td><td style="text-align:center;">180°</td><td style="text-align:left;">八月</td><td style="text-align:left;">酉月</td><td style="text-align:center;">气</td></tr><tr><td style="text-align:center;">19</td><td style="text-align:left;"><strong>寒露</strong></td><td style="text-align:left;">10月7—9日</td><td style="text-align:center;">195°</td><td style="text-align:left;">九月始</td><td style="text-align:left;">戌月起</td><td style="text-align:center;"><strong>节</strong></td></tr><tr><td style="text-align:center;">20</td><td style="text-align:left;">霜降</td><td style="text-align:left;">10月23—24日</td><td style="text-align:center;">210°</td><td style="text-align:left;">九月</td><td style="text-align:left;">戌月</td><td style="text-align:center;">气</td></tr><tr><td style="text-align:center;">21</td><td style="text-align:left;"><strong>立冬</strong></td><td style="text-align:left;">11月7—8日</td><td style="text-align:center;">225°</td><td style="text-align:left;">十月始</td><td style="text-align:left;">亥月起</td><td style="text-align:center;"><strong>节</strong></td></tr><tr><td style="text-align:center;">22</td><td style="text-align:left;">小雪</td><td style="text-align:left;">11月22—23日</td><td style="text-align:center;">240°</td><td style="text-align:left;">十月</td><td style="text-align:left;">亥月</td><td style="text-align:center;">气</td></tr><tr><td style="text-align:center;">23</td><td style="text-align:left;"><strong>大雪</strong></td><td style="text-align:left;">12月6—8日</td><td style="text-align:center;">255°</td><td style="text-align:left;">十一月始</td><td style="text-align:left;">子月起</td><td style="text-align:center;"><strong>节</strong></td></tr><tr><td style="text-align:center;">24</td><td style="text-align:left;">冬至</td><td style="text-align:left;">12月21—23日</td><td style="text-align:center;">270°</td><td style="text-align:left;">十一月</td><td style="text-align:left;">子月</td><td style="text-align:center;">气</td></tr></tbody></table><hr><h3 id="_4-2-节-vs-气-初学者最常混淆的区别" tabindex="-1">4.2 节 vs 气：初学者最常混淆的区别 <a class="header-anchor" href="#_4-2-节-vs-气-初学者最常混淆的区别" aria-label="Permalink to &quot;4.2 节 vs 气：初学者最常混淆的区别&quot;">​</a></h3><p>二十四节气，实际上分为两类：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>二十四节气</span></span>
<span class="line"><span>    ├── 十二&quot;节&quot;（换月节气）</span></span>
<span class="line"><span>    │   小寒·立春·惊蛰·清明·立夏·芒种</span></span>
<span class="line"><span>    │   小暑·立秋·白露·寒露·立冬·大雪</span></span>
<span class="line"><span>    │       = 换月的时间节点</span></span>
<span class="line"><span>    │       = 四柱八字中，月柱在此更换</span></span>
<span class="line"><span>    │       = 奇门遁甲在此换局（同时也是换元节点）</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └── 十二&quot;气&quot;（月内深化节气）</span></span>
<span class="line"><span>        大寒·雨水·春分·谷雨·小满·夏至</span></span>
<span class="line"><span>        大暑·处暑·秋分·霜降·小雪·冬至</span></span>
<span class="line"><span>            = 月内的气候深化节点</span></span>
<span class="line"><span>            = 四柱：不换月柱，但影响月内五行旺衰判断</span></span>
<span class="line"><span>            = 奇门：气同样是换元节点（每节气分三元，</span></span>
<span class="line"><span>              节与气均触发元的推进，共72局）</span></span></code></pre></div><p><strong>关键规则（术数实战必记）：</strong></p><blockquote><p>四柱八字的月柱，以<strong>节</strong>为换月标准，不以农历初一为准。</p></blockquote><p><strong>实例一（节气与农历一致）：</strong></p><blockquote><p>某人生于2026年7月22日<br> 农历：六月初八<br> 节气：已过小暑（7月7日），未到立秋（8月7日）<br> 月柱 = <strong>未月</strong> ✓</p></blockquote><p><strong>实例二（节气与农历不一致——最能说明问题的情况）：</strong></p><blockquote><p>某人甲，生于2026年2月15日<br> 农历：正月初八（农历正月）<br> 节气：立春为2月4日，已过节<br> 月柱 = <strong>寅月</strong> ✓</p><p>某人乙，生于2026年2月3日<br> 农历：正月初一（农历正月）<br> 节气：立春为2月4日，<strong>尚未过节</strong><br> 月柱 = <strong>丑月</strong>（上一个月柱）✓</p><p>→ 同是&quot;农历正月&quot;，甲的月柱是寅月，乙的月柱是丑月。<br> → 完全取决于是否已过立春，与农历几月无关。</p></blockquote><h3 id="_4-3-逐节详解" tabindex="-1">4.3 逐节详解 <a class="header-anchor" href="#_4-3-逐节详解" aria-label="Permalink to &quot;4.3 逐节详解&quot;">​</a></h3><blockquote><p>📷 <strong>图片位置说明：</strong> 每个节气标题下方预留图片位置，建议配对应节气的自然景观或传统画作。</p></blockquote><hr><h4 id="🌨-01-·-小寒" tabindex="-1">🌨 01 · 小寒 <a class="header-anchor" href="#🌨-01-·-小寒" aria-label="Permalink to &quot;🌨 01 · 小寒&quot;">​</a></h4><p><strong>太阳黄经 285° · 约1月5—7日 · 丑月起 · 十二月 · 节</strong></p><p>📷 <em>[配图：北方冬日，大雁调头，枯枝白雪，喜鹊筑巢]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：雁北乡（大雁开始调头向北）<br> 二候：鹊始巢（喜鹊开始筑巢）<br> 三候：雉始雊（野鸡开始鸣叫）</p></blockquote><p><strong>【画面感】</strong></p><p>一年中最冷的时节已经到来。天地一片肃静，大雪压枝，河面结冰。<br> 但大雁已经感知到北方将有阳气回升，开始调转方向。<br> 喜鹊在枝头开始筑巢——它们比人更早知道，春天不远了。</p><p>小寒，是冬天最深处的一声低语：我快走了。</p><p><strong>【术数意义】</strong></p><ul><li>丑月换月节点（小寒为丑月之节，过小寒方入丑月）</li><li>金气入库（丑为金库），寒气极盛，水旺金相，木气极弱</li><li>奇门：阴遁局运行中</li></ul><hr><h4 id="🥶-02-·-大寒" tabindex="-1">🥶 02 · 大寒 <a class="header-anchor" href="#🥶-02-·-大寒" aria-label="Permalink to &quot;🥶 02 · 大寒&quot;">​</a></h4><p><strong>太阳黄经 300° · 约1月20—21日 · 丑月 · 十二月 · 气</strong></p><p>📷 <em>[配图：冰封河面，母鸡孵蛋，鹰隼盘旋]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：鸡乳（母鸡开始孵蛋）<br> 二候：征鸟厉疾（鹰隼捕猎最为凶猛）<br> 三候：水泽腹坚（河流从表面到底部彻底冻实）</p></blockquote><p><strong>【画面感】</strong></p><p>大寒是冬天的最后一搏。河流从表面到底部彻底冻实，是一年中冰层最厚的时刻。<br> 但母鸡已经开始孵蛋——生命在极寒中悄悄启动。<br> 鹰隼在天空中盘旋，动作迅猛，这是它们一年中捕猎最凶猛的时候，<br> 因为它们也知道：冬天的猎物，不多了。</p><p>大寒之后，就是立春。终点即是起点。</p><p><strong>【术数意义】</strong></p><ul><li>丑月中气，金库将开，即将换寅月</li><li>大寒后约15天即立春，月柱将由丑换寅</li><li>此时起局仍用丑月参数，立春交节后换寅月</li></ul><hr><h4 id="🌱-03-·-立春" tabindex="-1">🌱 03 · 立春 <a class="header-anchor" href="#🌱-03-·-立春" aria-label="Permalink to &quot;🌱 03 · 立春&quot;">​</a></h4><p><strong>太阳黄经 315° · 约2月3—5日 · 寅月起 · 正月始 · 节</strong></p><p>📷 <em>[配图：冻土松动，鱼顶薄冰，田野初绿]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：东风解冻（东风吹来，冻土开始松动）<br> 二候：蛰虫始振（蛰伏��虫子开始微微蠕动）<br> 三候：鱼陟负冰（鱼顶着薄冰向上游）</p></blockquote><p><strong>【画面感】</strong></p><p>立春这一天，东风吹来，冻土开始松动。<br> 地下蛰伏了整个冬天的虫子，感受到震动，开始微微蠕动。<br> 河里的鱼，顶着还未完全融化的薄冰，往上游。<br> 你站在田野里，感觉不到暖意，风还是冷的，<br> 但土地的气息变了——有什么东西，醒了。</p><p>这就是立春：不是温暖，是苏醒。</p><p><strong>【术数意义】</strong></p><ul><li><strong>月柱换寅月</strong>（四柱八字以此为正月起点，非农历初一）</li><li><strong>术数体系中&quot;年&quot;的真正起点</strong>（以立春换年，非春节）</li><li>奇门遁甲：上元换局节点之一</li><li>寅月：甲木当令，阳木初生，生气最旺</li></ul><hr><h4 id="🌧-04-·-雨水" tabindex="-1">🌧 04 · 雨水 <a class="header-anchor" href="#🌧-04-·-雨水" aria-label="Permalink to &quot;🌧 04 · 雨水&quot;">​</a></h4><p><strong>太阳黄经 330° · 约2月18—20日 · 寅月 · 正月 · 气</strong></p><p>📷 <em>[配图：水獭捕鱼，大雁北飞，草木萌动]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：獭祭鱼（水獭把鱼摆在岸边，如同祭祀）<br> 二候：候雁北（大雁成群结队往北飞）<br> 三候：草木萌动（草木根须开始向上输送水分）</p></blockquote><p><strong>【画面感】</strong></p><p>雨水节气，降水形式从雪变成了雨。<br> 水獭把捕到的鱼摆在岸边，像是在祭祀——古人看到这个场景，<br> 就知道：河流解冻了，春天的水来了。<br> 大雁成群结队往北飞，草木的根须开始向上输送水分，<br> 枝头还没有叶，但已经有了隐隐的绿意。</p><p>雨水，是春天的第一口呼吸。</p><p><strong>【术数意义】</strong></p><ul><li>寅月中气，甲木旺盛，水气仍强（水生木）</li><li>雨水前后，木气由萌生转向旺盛</li><li>农历正月中，是寅月能量最饱满的阶段</li></ul><hr><h4 id="⚡-05-·-惊蛰" tabindex="-1">⚡ 05 · 惊蛰 <a class="header-anchor" href="#⚡-05-·-惊蛰" aria-label="Permalink to &quot;⚡ 05 · 惊蛰&quot;">​</a></h4><p><strong>太阳黄经 345° · 约3月5—7日 · 卯月起 · 二月始 · 节</strong></p><p>📷 <em>[配图：春雷滚过，桃花盛开，虫子破土]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：桃始华（桃花开放）<br> 二候：仓庚鸣（黄莺开始鸣叫）<br> 三候：鹰化为鸠（鹰隼进入繁殖期，斑鸠开始出现）</p></blockquote><p><strong>【画面感】</strong></p><p>第一声春雷滚过，大地震动。<br> 土里蛰伏的虫子，被雷声惊醒，纷纷破土而出。<br> 桃花开了，黄莺在枝头鸣叫，天空中的鹰隼不见了——<br> 古人说它们&quot;化为鸠&quot;，其实是鹰隼进入繁殖期躲起来了，而斑鸠开始出现。</p><p>惊蛰，是大地的一声炸响，把所有沉睡的生命全部叫醒。</p><p><strong>【术数意义】</strong></p><ul><li><strong>月柱换卯月</strong></li><li>奇门换局节点</li><li>卯月：乙木当令，木气帝旺（最旺）</li><li>卯月是一年中木气最纯粹、最旺盛的月份</li></ul><hr><h4 id="🌸-06-·-春分" tabindex="-1">🌸 06 · 春分 <a class="header-anchor" href="#🌸-06-·-春分" aria-label="Permalink to &quot;🌸 06 · 春分&quot;">​</a></h4><p><strong>太阳黄经 0°（360°） · 约3月20—21日 · 卯月 · 二月 · 气</strong></p><p>📷 <em>[配图：燕子归来，昼夜等长，春雷闪电]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：玄鸟至（燕子从南方飞回）<br> 二候：雷乃发声（雷声开始频繁）<br> 三候：始电（闪电开始出现）</p></blockquote><p><strong>【画面感】</strong></p><p>春分，昼夜等长。燕子从南方飞回来，在屋檐下筑巢。<br> 雷声开始频繁，闪电划过天空。<br> 站在春分这一天，你站在一个完美的平衡点上：<br> 白天和黑夜一样长，阴和阳一样重，冷和暖势均力敌。<br> 但从这一天起，阳气开始占上风。</p><p>春分，是春天的正中央。</p><p><strong>【术数意义】</strong></p><ul><li>卯月中气，木气极盛</li><li>春分点 = 黄经0°，是黄道坐标系的起算点，也是天文观测的重要基准</li><li>昼夜等长，阴阳平衡</li></ul><hr><h4 id="🌿-07-·-清明" tabindex="-1">🌿 07 · 清明 <a class="header-anchor" href="#🌿-07-·-清明" aria-label="Permalink to &quot;🌿 07 · 清明&quot;">​</a></h4><p><strong>太阳黄经 15° · 约4月4—6日 · 辰月起 · 三月始 · 节</strong></p><p>📷 <em>[配图：梧桐花开，雨后山野，扫墓祭祖]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：桐始华（梧桐花开）<br> 二候：田鼠化为鴽（田鼠不见，鹌鹑出现）<br> 三候：虹始见（雨后彩虹开始出现）</p></blockquote><p><strong>【画面感】</strong></p><p>清明，天气清朗，大地明净。梧桐花开，彩虹出现在雨后的天空。<br> 这是一年中空气最清透的时节——<br> 春雨洗过的山野，绿得发亮，远处的山看得格外清楚。<br> 清明扫墓，不只是习俗，<br> 是在这个天地最清明的时刻，与先人做一次最清晰的对话。</p><p><strong>【术数意义】</strong></p><ul><li><strong>月柱换辰月</strong></li><li>奇门换局节点</li><li>辰月：戊土当令，湿土，水库</li><li>春末，木气开始收敛（辰藏乙木·癸水·戊土）</li></ul><hr><h4 id="🌾-08-·-谷雨" tabindex="-1">🌾 08 · 谷雨 <a class="header-anchor" href="#🌾-08-·-谷雨" aria-label="Permalink to &quot;🌾 08 · 谷雨&quot;">​</a></h4><p><strong>太阳黄经 30° · 约4月19—21日 · 辰月 · 三月 · 气</strong></p><p>📷 <em>[配图：浮萍水面，布谷催种，戴胜落桑]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：萍始生（浮萍开始在水面生长）<br> 二候：鸣鸠拂其羽（布谷鸟拍打翅膀，催促播种）<br> 三候：戴胜降于桑（戴胜鸟落在桑树上）</p></blockquote><p><strong>【画面感】</strong></p><p>谷雨，是春天的最后一场大礼。<br> 雨水充沛，浮萍开始在水面生长，<br> 布谷鸟拍打翅膀，催促农人播种，<br> 戴胜鸟落在桑树上——蚕农知道，采桑养蚕的季节到了。<br> &quot;雨生百谷&quot;，这场雨，是大地给种子的最后一次滋润，<br> 之后，就是夏天的热烈生长。</p><p><strong>【术数意义】</strong></p><ul><li>辰月中气，湿土最旺，水库能量充盈</li><li>春季最后一个气，之后立夏换巳月</li><li>农耕历法中最重要的播种节气之一</li></ul><hr><h4 id="☀️-09-·-立夏" tabindex="-1">☀️ 09 · 立夏 <a class="header-anchor" href="#☀️-09-·-立夏" aria-label="Permalink to &quot;☀️ 09 · 立夏&quot;">​</a></h4><p><strong>太阳黄经 45° · 约5月5—7日 · 巳月起 · 四月始 · 节</strong></p><p>📷 <em>[配图：蛙声初起，蚯蚓出土，树荫浓密]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：蝼蝈鸣（蛙声突然响起）<br> 二候：蚯蚓出（蚯蚓从土里钻出来）<br> 三候：王瓜生（王瓜的藤蔓开始攀爬）</p></blockquote><p><strong>【画面感】</strong></p><p>立夏这一天，蛙声突然响起。<br> 蚯蚓从土里钻出来，王瓜的藤蔓开始攀爬。<br> 气温还不算高，但阳光的角度变了——照在身上，有了实实在在的热度。<br> 树荫变得浓密，知了还没叫，但你已经感觉到：<br> 夏天，真的来了。</p><p>立夏，是热烈的开场白。</p><p><strong>【术数意义】</strong></p><ul><li><strong>月柱换巳月</strong></li><li>奇门换局节点</li><li>巳月：丙火当令，火气长生，阳气极盛</li><li>巳中藏丙火·庚金·戊土，能量复杂</li></ul><hr><h4 id="🌻-10-·-小满" tabindex="-1">🌻 10 · 小满 <a class="header-anchor" href="#🌻-10-·-小满" aria-label="Permalink to &quot;🌻 10 · 小满&quot;">​</a></h4><p><strong>太阳黄经 60° · 约5月20—22日 · 巳月 · 四月 · 气</strong></p><p>📷 <em>[配图：麦田金黄，苦菜开花，将满未满]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：苦菜秀（苦菜开花）<br> 二候：靡草死（喜阴的草开始枯萎）<br> 三候：麦秋至（北方麦粒开始饱满）</p></blockquote><p><strong>【画面感】</strong></p><p>小满，麦粒开始饱满，但还没有完全成熟。<br> 苦菜开花，喜阴的草开始枯萎，<br> 北方的麦田一片金黄，但还要再等几天。<br> &quot;小满&quot;这个名字，说的是一种将满未满的状态——<br> 果实已经饱满，但还差那么一点点。</p><p>这是一种最美的张力：期待中的丰盛。</p><p><strong>【术数意义】</strong></p><ul><li>巳月中气，火气旺盛上升</li><li>小满前后，火气由长生走向旺盛</li><li>农历四月中，阳气持续积累</li></ul><hr><h4 id="🌿-11-·-芒种" tabindex="-1">🌿 11 · 芒种 <a class="header-anchor" href="#🌿-11-·-芒种" aria-label="Permalink to &quot;🌿 11 · 芒种&quot;">​</a></h4><p><strong>太阳黄经 75° · 约6月5—7日 · 午月起 · 五月始 · 节</strong></p><p>📷 <em>[配图：麦收稻种，螳螂出壳，农人忙碌]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：螳螂生（螳螂破壳而出）<br> 二候：鵙始鸣（伯劳鸟开始鸣叫）<br> 三候：反舌无声（春天鸣叫的鸟此时沉默）</p></blockquote><p><strong>【画面感】</strong></p><p>芒种，是最忙碌的节气。<br> 有芒的麦子要收割，有芒的稻子要播种——<br> 收与种，同时进行，农人在田间来回奔走。<br> 螳螂破壳而出，伯劳鸟开始鸣叫，<br> 而那些春天里唱歌的鸟，此刻都沉默了——<br> 因为所有的生命，都在全力以赴地生长和劳作。</p><p>芒种，是夏天的冲刺令。</p><p><strong>【术数意义】</strong></p><ul><li><strong>月柱换午月</strong></li><li>奇门换局节点</li><li>午月：丁火当令，火气帝旺（最旺）</li><li>午月是一年中火气最纯粹、最旺盛的月份</li></ul><hr><h4 id="🔆-12-·-夏至" tabindex="-1">🔆 12 · 夏至 <a class="header-anchor" href="#🔆-12-·-夏至" aria-label="Permalink to &quot;🔆 12 · 夏至&quot;">​</a></h4><p><strong>太阳黄经 90° · 约6月21—22日 · 午月 · 五月 · 气</strong></p><p>📷 <em>[配图：正午日影最短，知了长鸣，半夏草生]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：鹿角解（鹿角开始脱落）<br> 二候：蜩始鸣（知了第一声长鸣）<br> 三候：半夏生（半夏草开始生长）</p></blockquote><p><strong>【画面感】</strong></p><p>夏至，北半球白昼最长的一天。<br> 正午的阳光直射头顶，影子短得几乎消失。<br> 鹿角开始脱落（阳气极盛后开始收敛），<br> 知了第一声长鸣划破正午的寂静，<br> 半夏这味药草开始生长——它的名字就叫&quot;夏天过了一半&quot;。</p><p>夏至，是阳气的顶点，也是转折点。<br> 从这一天起，白昼开始缩短，阴气开始上升。<br> 盛极，必转。</p><p><strong>【术数意义】</strong></p><ul><li>午月中气，一阴生，阳极转阴</li><li>夏至 = 黄经90°，天文四极之一</li><li>午为火帝旺，同时一阴生，是阴阳转换最剧烈的节点</li><li>与冬至（一阳生）互为镜像</li></ul><hr><h4 id="🌡-13-·-小暑" tabindex="-1">🌡 13 · 小暑 <a class="header-anchor" href="#🌡-13-·-小暑" aria-label="Permalink to &quot;🌡 13 · 小暑&quot;">​</a></h4><p><strong>太阳黄经 105° · 约7月6—8日 · 未月起 · 六月始 · 节</strong></p><p>📷 <em>[配图：热风吹来，蟋蟀避暑，鹰隼练习]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：温风至（热风开始吹来）<br> 二候：蟋蟀居壁（蟋蟀躲进墙角避暑）<br> 三候：鹰始挚（鹰开始练习俯冲捕猎）</p></blockquote><p><strong>【画面感】</strong></p><p>小暑，热风开始吹来，不再是清凉的风，而是带着热气的、黏腻的风。<br> 蟋蟀躲进墙角避暑，鹰开始练习俯冲捕猎。<br> 这是夏天真正发威的开始——<br> 不是夏至那种&quot;极点&quot;的感觉，而是持续的、压倒性的热。</p><p>小暑，是夏天说：&quot;我还没完。&quot;</p><p><strong>【术数意义】</strong></p><ul><li><strong>月柱换未月</strong></li><li>奇门换局节点</li><li>未月：己土当令，燥土，木库</li><li>未月是一年中最热的月份（三伏多在此月）</li><li>火气开始入库（未为火墓），热而不烈</li></ul><hr><h4 id="🌊-14-·-大暑" tabindex="-1">🌊 14 · 大暑 <a class="header-anchor" href="#🌊-14-·-大暑" aria-label="Permalink to &quot;🌊 14 · 大暑&quot;">​</a></h4><p><strong>太阳黄经 120° · 约7月22—24日 · 未月 · 六月 · 气</strong></p><p>📷 <em>[配图：萤火虫闪烁，土地湿热，大雨骤来]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：腐草为萤（腐草化为萤火虫）<br> 二候：土润溽暑（土地湿热黏腻，暑气蒸腾）<br> 三候：大雨时行（大雨说来就来）</p></blockquote><p><strong>【画面感】</strong></p><p>大暑，是一年中最热的时节。<br> 腐草化为萤火虫（古人的浪漫观察），<br> 土地湿热黏腻，暑气蒸腾，大雨说来就来，雨后更闷热。<br> 萤火虫在夜晚的草丛中闪烁——<br> 这是大暑给人的一点温柔：<br> 最热的夜晚，有最美的萤光。</p><p><strong>【术数意义】</strong></p><ul><li>未月中气，暑气最盛，火入木库</li><li>大暑前后是三伏中的中伏、末伏</li><li>未月末，即将换申月（立秋），金气将起</li></ul><hr><h4 id="🍂-15-·-立秋" tabindex="-1">🍂 15 · 立秋 <a class="header-anchor" href="#🍂-15-·-立秋" aria-label="Permalink to &quot;🍂 15 · 立秋&quot;">​</a></h4><p><strong>太阳黄经 135° · 约8月7—9日 · 申月起 · 七月始 · 节</strong></p><p>📷 <em>[配图：凉风初至，白露降草，寒蝉鸣叫]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：凉风至（早晨的风有了一丝凉意）<br> 二候：白露降（草叶上开始出现白露）<br> 三候：寒蝉鸣（寒蝉开始鸣叫，声音沙哑苍凉）</p></blockquote><p><strong>【画面感】</strong></p><p>立秋这一天，早晨的风突然变了——<br> 还是热的，但有一丝说不清的凉意混在里面。<br> 草叶上开始出现白露，寒蝉开始鸣叫，<br> 声音和夏天的知了不一样，带着一点沙哑和苍凉。<br> 树叶还是绿的，但你知道：秋天的信使，已经到了。</p><p>立秋，是大自然发出的第一封秋天的信。</p><p><strong>【术数意义】</strong></p><ul><li><strong>月柱换申月</strong></li><li>奇门换局节点</li><li>申月：庚金当令，金气长生，肃杀之气始</li><li>申中藏庚金·壬水·戊土，水气开始萌生</li></ul><hr><h4 id="🌫-16-·-处暑" tabindex="-1">🌫 16 · 处暑 <a class="header-anchor" href="#🌫-16-·-处暑" aria-label="Permalink to &quot;🌫 16 · 处暑&quot;">​</a></h4><p><strong>太阳黄经 150° · 约8月22—24日 · 申月 · 七月 · 气</strong></p><p>📷 <em>[配图：鹰祭猎物，天地肃杀，禾稻成熟]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：鹰乃祭鸟（鹰大量捕猎，猎物摆开如祭）<br> 二候：天地始肃（天地开始肃杀）<br> 三候：禾乃登（庄稼开始成熟）</p></blockquote><p><strong>【画面感】</strong></p><p>&quot;处&quot;，是终止、躲藏的意思。处暑，暑气终于躲起来了。<br> 鹰开始大量捕猎，把猎物摆开——古人说这是在&quot;祭鸟&quot;，<br> 天地开始肃杀，庄稼开始成熟。<br> 白天还热，但早晚已经凉快，夜晚可以盖薄被了。</p><p>处暑，是夏天最后的挣扎，也是秋天正式接管的宣告。</p><p><strong>【术数意义】</strong></p><ul><li>申月中气，金气旺盛，水气萌生</li><li>处暑后，暑气退，秋意渐浓</li><li>申月水长生，壬水在此开始积累能量</li></ul><hr><h4 id="💧-17-·-白露" tabindex="-1">💧 17 · 白露 <a class="header-anchor" href="#💧-17-·-白露" aria-label="Permalink to &quot;💧 17 · 白露&quot;">​</a></h4><p><strong>太阳黄经 165° · 约9月7—9日 · 酉月起 · 八月始 · 节</strong></p><p>📷 <em>[配图：草叶白露，大雁南来，群鸟储食]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：鸿雁来（大雁从北方飞来）<br> 二候：玄鸟归（燕子开始南归）<br> 三候：群鸟养羞（各种鸟开始储备食物）</p></blockquote><p><strong>【画面感】</strong></p><p>白露，清晨的草地上铺满了白色的露珠。<br> 大雁从北方飞来，燕子开始南归，各种鸟开始储备食物过冬。<br> 白露的露水，是秋天最美的细节——<br> 在阳光照到之前，每一片草叶上都挂着一颗晶莹的水珠，<br> 像是大地在黎明前悄悄哭泣，又像是在轻声祝福。</p><p><strong>【术数意义】</strong></p><ul><li><strong>月柱换酉月</strong></li><li>奇门换局节点</li><li>酉月：辛金当令，金气帝旺（最旺）</li><li>酉月是一年中金气最纯粹的月份</li></ul><hr><h4 id="🍁-18-·-秋分" tabindex="-1">🍁 18 · 秋分 <a class="header-anchor" href="#🍁-18-·-秋分" aria-label="Permalink to &quot;🍁 18 · 秋分&quot;">​</a></h4><p><strong>太阳黄经 180° · 约9月22—24日 · 酉月 · 八月 · 气</strong></p><p>📷 <em>[配图：昼夜等长，雷声消失，水塘干涸]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：雷始收声（雷声消失）<br> 二候：蛰虫坯户（蛰虫开始用泥土封住洞口）<br> 三候：水始涸（水塘开始干涸）</p></blockquote><p><strong>【画面感】</strong></p><p>秋分，再一次昼夜等长。<br> 雷声消失了，蛰虫开始用泥土封住洞口准备冬眠，水塘开始干涸。<br> 站在秋分这一天，和春分一样站在平衡点上，但感觉完全不同——<br> 春分是万物向上的平衡，秋分是万物向内的平衡。<br> 一个是出发，一个是归途。</p><p><strong>【术数意义】</strong></p><ul><li>酉月中气，金气极盛</li><li>秋分 = 黄经180°，天文四极之一</li><li>与春分互为镜像，阴气开始占主导</li></ul><hr><h4 id="🌰-19-·-寒露" tabindex="-1">🌰 19 · 寒露 <a class="header-anchor" href="#🌰-19-·-寒露" aria-label="Permalink to &quot;🌰 19 · 寒露&quot;">​</a></h4><p><strong>太阳黄经 195° · 约10月7—9日 · 戌月起 · 九月始 · 节</strong></p><p>📷 <em>[配图：菊花盛开，大雁继续南飞，层林尽染]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：鸿雁来宾（大雁继续南飞）<br> 二候：雀入大水为蛤（麻雀不见，蛤蜊出现）<br> 三候：菊有黄华（菊花盛开，金黄一片）</p></blockquote><p><strong>【画面感】</strong></p><p>白露的露水是凉的，寒露的露水是冷的。<br> 大雁继续南飞，麻雀不见了（古人说它们&quot;入水变成蛤蜊&quot;，<br> 是对候鸟迁徙的浪漫误读），菊花盛开，金黄一片。<br> 寒露，是秋天最美的时节——<br> 天高气爽，层林尽染，<br> 但每一片美丽的红叶，都是在告别。</p><p><strong>【术数意义】</strong></p><ul><li><strong>月柱换戌月</strong></li><li>奇门换局节点</li><li>戌月：戊土当令，燥土，火库</li><li>金气开始收敛，戌藏戊土·辛金·丁火</li></ul><hr><h4 id="🍂-20-·-霜降" tabindex="-1">🍂 20 · 霜降 <a class="header-anchor" href="#🍂-20-·-霜降" aria-label="Permalink to &quot;🍂 20 · 霜降&quot;">​</a></h4><p><strong>太阳黄经 210° · 约10月23—24日 · 戌月 · 九月 · 气</strong></p><p>📷 <em>[配图：白霜覆屋，草木黄落，蛰虫低头]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：豺乃祭兽（豺狼储备猎物，摆开如祭）<br> 二候：草木黄落（草木彻底变黄，叶子纷纷落下）<br> 三候：蛰虫咸俯（蛰虫全部低头，进入冬眠准备）</p></blockquote><p><strong>【画面感】</strong></p><p>霜降，第一场霜来了。<br> 清晨出门，屋顶、草地、车顶，都覆着一层白霜。<br> 草木彻底变黄，叶子纷纷落下，蛰虫全部低头，进入冬眠的准备状态。<br> 豺狼把猎物摆开——古人说这是在&quot;祭兽&quot;，<br> 其实是它们在储备过冬的食物。</p><p>霜降，是秋天的最后一课：学会储藏，学会等待。</p><p><strong>【术数意义】</strong></p><ul><li>戌月中气，火库能量充盈，金气入库</li><li>霜降后，秋气彻底收尾，即将换亥月</li><li>戌月末，阳气大幅收敛</li></ul><hr><h4 id="❄️-21-·-立冬" tabindex="-1">❄️ 21 · 立冬 <a class="header-anchor" href="#❄️-21-·-立冬" aria-label="Permalink to &quot;❄️ 21 · 立冬&quot;">​</a></h4><p><strong>太阳黄经 225° · 约11月7—8日 · 亥月起 · 十月始 · 节</strong></p><p>📷 <em>[配图：水面结冰，土地冻硬，北方吃饺子]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：水始冰（水面开始结冰）<br> 二候：地始冻（土地开始冻硬）<br> 三候：雉入大水为蜃（野鸡不见，大蛤出现）</p></blockquote><p><strong>【画面感】</strong></p><p>立冬，水面开始结冰，土地开始冻硬。<br> 野鸡不见了（古人说它们&quot;入水变成大蛤&quot;，同样是候鸟迁徙的浪漫误读）。<br> 立冬这一天，北方人要吃饺子——<br> 因为冬天来了，要犒劳自己，也要储备能量，准备过冬。</p><p>立冬，是大地发出的一声宣告：封存，开始。</p><p><strong>【术数意义】</strong></p><ul><li><strong>月柱换亥月</strong></li><li>奇门换局节点</li><li>亥月：壬水当令，水气旺盛，木气长生</li><li>亥中藏壬水·甲木，木气开始在水中萌生</li></ul><hr><h4 id="🌨-22-·-小雪" tabindex="-1">🌨 22 · 小雪 <a class="header-anchor" href="#🌨-22-·-小雪" aria-label="Permalink to &quot;🌨 22 · 小雪&quot;">​</a></h4><p><strong>太阳黄经 240° · 约11月22—23日 · 亥月 · 十月 · 气</strong></p><p>📷 <em>[配图：彩虹消失，天地封闭，薄雪初降]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：虹藏不见（彩虹消失）<br> 二候：天气上升地气下降（天地之间的交流暂时中断）<br> 三候：闭塞而成冬（万物封闭，冬天正式成形）</p></blockquote><p><strong>【画面感】</strong></p><p>小雪，天空中开始飘雪，但雪量不大，落地即化，或只是薄薄一层。<br> 彩虹消失了，天气上升、地气下降——<br> 天地之间的交流，暂时中断，万物开始各自封闭，进入冬天的状态。</p><p>小雪，是冬天递来的第一张名片：轻轻的，但清清楚楚。</p><p><strong>【术数意义】</strong></p><ul><li>亥月中气，水气极旺，木气在水中积累</li><li>小雪前后，阴气持续加强</li><li>亥月末，即将换子月（大雪）</li></ul><hr><h4 id="⛄-23-·-大雪" tabindex="-1">⛄ 23 · 大雪 <a class="header-anchor" href="#⛄-23-·-大雪" aria-label="Permalink to &quot;⛄ 23 · 大雪&quot;">​</a></h4><p><strong>太阳黄经 255° · 约12月6—8日 · 子月起 · 十一月始 · 节</strong></p><p>📷 <em>[配图：大雪纷飞，荔挺草破冰而出，虎始交配]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：鹖鴠不鸣（寒号鸟不再鸣叫）<br> 二候：虎始交（老虎开始交配，阳气在极寒中萌动）<br> 三候：荔挺出（荔挺草破冰而出）</p></blockquote><p><strong>【画面感】</strong></p><p>大雪，雪量大了，真正的冬天降临。<br> 寒号鸟不再鸣叫，老虎开始交配（阳气在极寒中萌动），<br> 荔挺草破冰而出——<br> 这是大雪节气最神奇的物候：在最冷的时节，有一种草，反而开始生长。<br> 这就是&quot;一阳生&quot;的预兆——<br> 最深的黑暗里，藏着最初的光。</p><p><strong>【术数意义】</strong></p><ul><li><strong>月柱换子月</strong></li><li>奇门换局节点</li><li>子月：癸水当令，水气帝旺（最旺）</li><li>子月是一年中水气最纯粹的月份，一阳初生</li></ul><hr><h4 id="🌙-24-·-冬至" tabindex="-1">🌙 24 · 冬至 <a class="header-anchor" href="#🌙-24-·-冬至" aria-label="Permalink to &quot;🌙 24 · 冬至&quot;">​</a></h4><p><strong>太阳黄经 270° · 约12月21—23日 · 子月 · 十一月 · 气</strong></p><p>📷 <em>[配图：日影最长，家人围坐，地下泉水涌动]</em></p><p><strong>【原典物候】</strong>《逸周书·时训解》：</p><blockquote><p>初候：蚯蚓结（蚯蚓蜷缩成结）<br> 二候：麋角解（麋鹿角开始脱落）<br> 三候：水泉动（地下泉水开始涌动）</p></blockquote><p><strong>【画面感】</strong></p><p>冬至，北半球白昼最短的一天。<br> 正午的阳光斜斜地照来，影子拉得很长。<br> 蚯蚓蜷缩成结，麋鹿角开始脱落（与夏至鹿角解对应，一阴一阳的镜像），<br> 地下的泉水开始涌动——因为一阳生了，地下的热量开始向上传递。<br> 冬至这一天，家家户户吃汤圆、吃饺子，围坐在一起，<br> 庆祝的不是&quot;最冷的一天&quot;，而是：<br> 从今天起，白昼开始变长了。</p><p>冬至，是整个节气体系的原点，也是新一轮循环的起点。</p><p><strong>【术数意义】</strong></p><ul><li>子月中气，一阳生，阴极转阳</li><li>冬至 = 黄经270°，天文四极之一</li><li>奇门遁甲：冬至起上元阳遁一局，是全年起局的基准点</li><li>与夏至互为镜像，是整个干支时间体系的天文锚点</li></ul><h2 id="五、节气的天文本质" tabindex="-1">五、节气的天文本质 <a class="header-anchor" href="#五、节气的天文本质" aria-label="Permalink to &quot;五、节气的天文本质&quot;">​</a></h2><h3 id="_5-1-节气-太阳在黄道上的位置" tabindex="-1">5.1 节气 = 太阳在黄道上的位置 <a class="header-anchor" href="#_5-1-节气-太阳在黄道上的位置" aria-label="Permalink to &quot;5.1 节气 = 太阳在黄道上的位置&quot;">​</a></h3><p>节气的本质，是一个太阳历坐标系：</p><ul><li><strong>黄道</strong> = 地球公转轨道在天球上的投影</li><li><strong>二十四节气</strong> = 将黄道360°等分为24段，每段15°</li><li><strong>节气时刻</strong> = 太阳到达该黄经度数的精确时刻</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">四个极值节气</th><th style="text-align:center;">黄经</th><th style="text-align:left;">天文含义</th></tr></thead><tbody><tr><td style="text-align:left;">春分</td><td style="text-align:center;">0°</td><td style="text-align:left;">太阳直射赤道，昼夜等长，北半球春季开始</td></tr><tr><td style="text-align:left;">夏至</td><td style="text-align:center;">90°</td><td style="text-align:left;">太阳直射北回归线，北半球白昼最长</td></tr><tr><td style="text-align:left;">秋分</td><td style="text-align:center;">180°</td><td style="text-align:left;">太阳直射赤道，昼夜等长，北半球秋季开始</td></tr><tr><td style="text-align:left;">冬至</td><td style="text-align:center;">270°</td><td style="text-align:left;">太阳直射南回归线，北半球白昼最短</td></tr></tbody></table><hr><h3 id="_5-2-为什么节气是阳历而非阴历" tabindex="-1">5.2 为什么节气是阳历而非阴历？ <a class="header-anchor" href="#_5-2-为什么节气是阳历而非阴历" aria-label="Permalink to &quot;5.2 为什么节气是阳历而非阴历？&quot;">​</a></h3><p>这是理解节气最重要的认知：</p><blockquote><p>❌ <strong>常见误解：</strong> 节气是农历（阴历）的一部分<br> ✅ <strong>正确理解：</strong> 节气是独立的太阳历，与阴历无关</p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>农历（阴历）= 以月亮周期为基准（朔望月约29.5天）</span></span>
<span class="line"><span>节气        = 以太阳位置为基准（回归年 ÷ 24）</span></span></code></pre></div><p>所以：</p><ul><li>节气在**公历（阳历）**中，日期几乎固定（误差1—2天）</li><li>节气在<strong>农历</strong>中，日期每年不同（因为农历月份在变）</li></ul><p><strong>例：冬至</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">历法</th><th style="text-align:left;">日期</th></tr></thead><tbody><tr><td style="text-align:left;">公历</td><td style="text-align:left;">每年12月21—23日（非常稳定）</td></tr><tr><td style="text-align:left;">农历</td><td style="text-align:left;">有时十一月初，有时十一月中，每年不同</td></tr></tbody></table><blockquote><p>节气是中国古代独立发展的太阳历系统，<br> 它被&quot;嵌入&quot;农历，形成阴阳合历，<br> 但它本身的天文基础是纯粹的太阳运动。</p></blockquote><hr><h3 id="_5-3-节气的精确性" tabindex="-1">5.3 节气的精确性 <a class="header-anchor" href="#_5-3-节气的精确性" aria-label="Permalink to &quot;5.3 节气的精确性&quot;">​</a></h3><p>现代天文学验证：</p><ul><li>回归年 = 365.2422天</li><li>每个节气间隔 = 365.2422 ÷ 24 ≈ 15.22天</li></ul><p>古人用土圭测影，能精确测定冬至夏至，误差在1天以内。<br> 这在没有现代仪器的条件下，是极其了不起的天文成就。</p><hr><h2 id="六、节气与术数的接口" tabindex="-1">六、节气与术数的接口 <a class="header-anchor" href="#六、节气与术数的接口" aria-label="Permalink to &quot;六、节气与术数的接口&quot;">​</a></h2><h3 id="_6-1-奇门遁甲-节气是起局的时间基准" tabindex="-1">6.1 奇门遁甲：节气是起局的时间基准 <a class="header-anchor" href="#_6-1-奇门遁甲-节气是起局的时间基准" aria-label="Permalink to &quot;6.1 奇门遁甲：节气是起局的时间基准&quot;">​</a></h3><p>奇门遁甲以节气为时间单位起局：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一年 = 24个节气</span></span>
<span class="line"><span>每个节气 = 上中下三元</span></span>
<span class="line"><span>每元 = 5天</span></span>
<span class="line"><span></span></span>
<span class="line"><span>上元（第1—5天）</span></span>
<span class="line"><span>中元（第6—10天）</span></span>
<span class="line"><span>下元（第11—15天）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>节气 × 三元 × 阴阳遁 = 奇门局的完整时间坐标</span></span></code></pre></div><p><strong>关键：</strong> 奇门换局，以节气交节的精确时刻为准，不是以当天零点为准。<br> 交节前一秒和交节后一秒，用的是不同的局。</p><hr><h3 id="_6-2-四柱八字-月柱的换月以节气为准" tabindex="-1">6.2 四柱八字：月柱的换月以节气为准 <a class="header-anchor" href="#_6-2-四柱八字-月柱的换月以节气为准" aria-label="Permalink to &quot;6.2 四柱八字：月柱的换月以节气为准&quot;">​</a></h3><p>这是节气在四柱中最重要的应用规则：</p><blockquote><p>❌ <strong>错误理解：</strong> 农历几月 = 用几月的地支<br> ✅ <strong>正确规则：</strong> 以节（十二节）为换月标准</p></blockquote><p><strong>十二节与对应月柱：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">节气</th><th style="text-align:left;">约公历日期</th><th style="text-align:left;">月柱</th></tr></thead><tbody><tr><td style="text-align:left;">小寒</td><td style="text-align:left;">约1月6日</td><td style="text-align:left;">丑月开始</td></tr><tr><td style="text-align:left;">立春</td><td style="text-align:left;">约2月4日</td><td style="text-align:left;">寅月开始</td></tr><tr><td style="text-align:left;">惊蛰</td><td style="text-align:left;">约3月6日</td><td style="text-align:left;">卯月开始</td></tr><tr><td style="text-align:left;">清明</td><td style="text-align:left;">约4月5日</td><td style="text-align:left;">辰月开始</td></tr><tr><td style="text-align:left;">立夏</td><td style="text-align:left;">约5月6日</td><td style="text-align:left;">巳月开始</td></tr><tr><td style="text-align:left;">芒种</td><td style="text-align:left;">约6月6日</td><td style="text-align:left;">午月开始</td></tr><tr><td style="text-align:left;">小暑</td><td style="text-align:left;">约7月7日</td><td style="text-align:left;">未月开始</td></tr><tr><td style="text-align:left;">立秋</td><td style="text-align:left;">约8月7日</td><td style="text-align:left;">申月开始</td></tr><tr><td style="text-align:left;">白露</td><td style="text-align:left;">约9月8日</td><td style="text-align:left;">酉月开始</td></tr><tr><td style="text-align:left;">寒露</td><td style="text-align:left;">约10月8日</td><td style="text-align:left;">戌月开始</td></tr><tr><td style="text-align:left;">立冬</td><td style="text-align:left;">约11月7日</td><td style="text-align:left;">亥月开始</td></tr><tr><td style="text-align:left;">大雪</td><td style="text-align:left;">约12月7日</td><td style="text-align:left;">子月开始</td></tr></tbody></table><hr><h3 id="_6-3-六爻与择日-节气影响月建判断" tabindex="-1">6.3 六爻与择日：节气影响月建判断 <a class="header-anchor" href="#_6-3-六爻与择日-节气影响月建判断" aria-label="Permalink to &quot;6.3 六爻与择日：节气影响月建判断&quot;">​</a></h3><ul><li><strong>六爻：</strong> 月建（当月地支）影响爻的旺衰，月建以节气换月为准</li><li><strong>择日：</strong> 建除十二神以节气月建为基准起算</li><li><strong>大六壬：</strong> 月将（太阳所在宫位）以节气为换将时间</li></ul><h3 id="_6-4-中医-节气是养生的时间坐标" tabindex="-1">6.4 中医：节气是养生的时间坐标 <a class="header-anchor" href="#_6-4-中医-节气是养生的时间坐标" aria-label="Permalink to &quot;6.4 中医：节气是养生的时间坐标&quot;">​</a></h3><p>节气与中医的关系，是最容易被忽略、却极为重要的一个接口。</p><p><strong>【原典】</strong>《黄帝内经·素问·四气调神大论》：</p><blockquote><p>&quot;春三月，此谓发陈，天地俱生，万物以荣……<br> 夏三月，此谓蕃秀，天地气交，万物华实……<br> 秋三月，此谓容平，天气以急，地气以明……<br> 冬三月，此谓闭藏，水冰地坼，无扰乎阳……&quot;</p></blockquote><p>中医以节气为时间基准，指导：</p><table tabindex="0"><thead><tr><th style="text-align:left;">方面</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;">饮食调整</td><td style="text-align:left;">应季而食，顺应节气变化选择食材</td></tr><tr><td style="text-align:left;">作息规律</td><td style="text-align:left;">顺应昼夜长短，春夏晚睡早起，秋冬早睡晚起</td></tr><tr><td style="text-align:left;">节气灸</td><td style="text-align:left;">冬至·夏至·三伏·三九为重要施灸节点，&quot;冬病夏治&quot;</td></tr><tr><td style="text-align:left;">情志调养</td><td style="text-align:left;">春生·夏长·秋收·冬藏，对应情志的舒展·喜悦·收敛·静藏</td></tr></tbody></table><blockquote><p>节气不只是历法工具，更是中医&quot;天人合一&quot;思想的时间载体。<br> 读《黄帝内经》，节气是绕不过去的基础背景知识。</p></blockquote><hr><h3 id="_6-5-一个关键细节-交节时刻的精确性" tabindex="-1">6.5 一个关键细节：交节时刻的精确性 <a class="header-anchor" href="#_6-5-一个关键细节-交节时刻的精确性" aria-label="Permalink to &quot;6.5 一个关键细节：交节时刻的精确性&quot;">​</a></h3><p>节气不是&quot;某一天&quot;，而是某一天的某一<strong>时刻</strong>。</p><p><strong>例：2026年小暑</strong></p><blockquote><p>精确交节时刻：2026年7月7日 05时14分（北京时间）</p><p>7月7日 05时13分出生 → 月柱仍为<strong>午月</strong>（芒种后）<br> 7月7日 05时15分出生 → 月柱已换<strong>未月</strong>（小暑后）</p></blockquote><p>相差两分钟，月柱不同。</p><p>这就是为什么传统命理师在排四柱时，<br> 必须查精确的节气交节时刻表，而不能只看日期。</p><hr><h2 id="七、节气的文化层-从历法到生活" tabindex="-1">七、节气的文化层：从历法到生活 <a class="header-anchor" href="#七、节气的文化层-从历法到生活" aria-label="Permalink to &quot;七、节气的文化层：从历法到生活&quot;">​</a></h2><h3 id="_7-1-节气与农业-古代农民的操作手册" tabindex="-1">7.1 节气与农业：古代农民的操作手册 <a class="header-anchor" href="#_7-1-节气与农业-古代农民的操作手册" aria-label="Permalink to &quot;7.1 节气与农业：古代农民的操作手册&quot;">​</a></h3><p>二十四节气，本质上是农业操作指南：</p><table tabindex="0"><thead><tr><th style="text-align:left;">节气</th><th style="text-align:left;">农事活动</th></tr></thead><tbody><tr><td style="text-align:left;">雨水</td><td style="text-align:left;">施肥，北方开始春耕准备</td></tr><tr><td style="text-align:left;">惊蛰</td><td style="text-align:left;">春耕开始，播种早稻</td></tr><tr><td style="text-align:left;">清明</td><td style="text-align:left;">植树，种棉花，春耕大忙</td></tr><tr><td style="text-align:left;">谷雨</td><td style="text-align:left;">播种谷物，&quot;谷雨前后，种瓜点豆&quot;</td></tr><tr><td style="text-align:left;">芒种</td><td style="text-align:left;">收割小麦，播种水稻，&quot;芒种忙，忙着种&quot;</td></tr><tr><td style="text-align:left;">大暑</td><td style="text-align:left;">防暑，水稻追肥</td></tr><tr><td style="text-align:left;">白露</td><td style="text-align:left;">收割高粱，&quot;白露秋分夜，一夜冷一夜&quot;</td></tr><tr><td style="text-align:left;">寒露</td><td style="text-align:left;">收割晚稻，&quot;寒露不摘棉，霜打莫怨天&quot;</td></tr><tr><td style="text-align:left;">霜降</td><td style="text-align:left;">收割最后的庄稼，储藏蔬菜</td></tr><tr><td style="text-align:left;">冬至</td><td style="text-align:left;">冬灌，储备农具，准备来年</td></tr></tbody></table><hr><h3 id="_7-2-节气与饮食-二十四节气的食俗" tabindex="-1">7.2 节气与饮食：二十四节气的食俗 <a class="header-anchor" href="#_7-2-节气与饮食-二十四节气的食俗" aria-label="Permalink to &quot;7.2 节气与饮食：二十四节气的食俗&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">节气</th><th style="text-align:left;">传统食俗</th><th style="text-align:left;">来源与含义</th></tr></thead><tbody><tr><td style="text-align:left;">冬至</td><td style="text-align:left;">北方吃饺子，南方吃汤圆</td><td style="text-align:left;">庆祝一阳生，团圆御寒</td></tr><tr><td style="text-align:left;">立春</td><td style="text-align:left;">吃春卷、春饼（咬春）</td><td style="text-align:left;">迎接春天，尝新鲜蔬菜</td></tr><tr><td style="text-align:left;">清明</td><td style="text-align:left;">吃青团</td><td style="text-align:left;">江南习俗，艾草染色糯米团</td></tr><tr><td style="text-align:left;">谷雨</td><td style="text-align:left;">喝谷雨茶</td><td style="text-align:left;">谷雨前后采的茶，清热解毒</td></tr><tr><td style="text-align:left;">立夏</td><td style="text-align:left;">吃立夏蛋</td><td style="text-align:left;">民间认为立夏吃蛋可以强身</td></tr><tr><td style="text-align:left;">夏至</td><td style="text-align:left;">北方吃面条，南方吃荔枝</td><td style="text-align:left;">&quot;冬至饺子夏至面&quot;</td></tr><tr><td style="text-align:left;">立秋</td><td style="text-align:left;">贴秋膘（吃肉）</td><td style="text-align:left;">补充夏天消耗的体力</td></tr><tr><td style="text-align:left;">霜降</td><td style="text-align:left;">吃柿子</td><td style="text-align:left;">&quot;霜降吃柿子，不会流鼻涕&quot;</td></tr><tr><td style="text-align:left;">立冬</td><td style="text-align:left;">北方吃饺子</td><td style="text-align:left;">与立春、冬至共同构成饺子三节</td></tr><tr><td style="text-align:left;">大寒</td><td style="text-align:left;">吃八宝粥</td><td style="text-align:left;">腊月将近，储备热量</td></tr></tbody></table><hr><h3 id="_7-3-节气与诗歌-古典文学中的节气意象" tabindex="-1">7.3 节气与诗歌：古典文学中的节气意象 <a class="header-anchor" href="#_7-3-节气与诗歌-古典文学中的节气意象" aria-label="Permalink to &quot;7.3 节气与诗歌：古典文学中的节气意象&quot;">​</a></h3><p>节气是古典诗词中最高频的时间意象之一：</p><p><strong>冬至：</strong></p><blockquote><p>&quot;天时人事日相催，冬至阳生春又来。&quot;<br> ——杜甫《小至》</p></blockquote><p><strong>清明：</strong></p><blockquote><p>&quot;清明时节雨纷纷，路上行人欲断魂。&quot;<br> ——杜牧《清明》</p></blockquote><p><strong>春分：</strong></p><blockquote><p>&quot;春分雨脚落声微，柳岸斜风带客归。&quot;<br> ——徐铉《春分日》</p></blockquote><p><strong>夏至：</strong></p><blockquote><p>&quot;昼晷已云极，宵漏自此长。&quot;<br> ——韦应物《夏至避暑北池》</p></blockquote><p><strong>白露：</strong></p><blockquote><p>&quot;蒹葭苍苍，白露为霜。所谓伊人，在水一方。&quot;<br> ——《诗经·秦风·蒹葭》</p></blockquote><p><strong>霜降：</strong></p><blockquote><p>&quot;停车坐爱枫林晚，霜叶红于二月花。&quot;<br> ——杜牧《山行》</p></blockquote><h3 id="_7-4-为什么2016年列入非遗" tabindex="-1">7.4 为什么2016年列入非遗？ <a class="header-anchor" href="#_7-4-为什么2016年列入非遗" aria-label="Permalink to &quot;7.4 为什么2016年列入非遗？&quot;">​</a></h3><p>2016年11月，&quot;二十四节气——中国人通过观察太阳周年运动而形成的时间知识体系及其实践&quot;<br> 被列入联合国教科文组织人类非物质文化遗产代表作名录。</p><p><strong>UNESCO的评价：</strong></p><blockquote><p>&quot;二十四节气是中国人认知一年中时令、气候、物候等方面变化规律所形成的知识体系和社会实践。<br> 它深刻影响着人们的思维方式和行为准则，是中华民族文化认同的重要载体。&quot;</p></blockquote><p><strong>为什么值得这个认定：</strong></p><ul><li>这是人类历史上持续使用时间最长的天文历法系统之一（超过2000年）</li><li>它不只是历法，更是完整的自然观察体系（七十二候）</li><li>它至今仍活在日常生活中（农业、饮食、民俗、中医）</li><li>它是纯粹的中国原创，没有受到外来历法体系的影响</li></ul><h2 id="八、现代解读-节气本质上是什么" tabindex="-1">八、现代解读：节气本质上是什么？ <a class="header-anchor" href="#八、现代解读-节气本质上是什么" aria-label="Permalink to &quot;八、现代解读：节气本质上是什么？&quot;">​</a></h2><h3 id="_8-1-不是-迷信-是精确的天文坐标系" tabindex="-1">8.1 不是&quot;迷信&quot;，是精确的天文坐标系 <a class="header-anchor" href="#_8-1-不是-迷信-是精确的天文坐标系" aria-label="Permalink to &quot;8.1 不是&quot;迷信&quot;，是精确的天文坐标系&quot;">​</a></h3><p>节气经常被误解为&quot;封建迷信&quot;或&quot;农村习俗&quot;，这是一个严重的认知偏差。</p><p><strong>节气的本质：</strong></p><ul><li>是基于精确天文观测的时间系统</li><li>是经过2000年以上实践验证的农业指导体系</li><li>是现代天文学可以完全验证的太阳历坐标</li></ul><p>现代天文软件计算节气时刻，与古代历法的误差，在现代精密测量下仅为分钟级别。</p><h3 id="_8-2-节气思维-vs-公历思维" tabindex="-1">8.2 节气思维 vs 公历思维 <a class="header-anchor" href="#_8-2-节气思维-vs-公历思维" aria-label="Permalink to &quot;8.2 节气思维 vs 公历思维&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">公历思维</th><th style="text-align:left;">节气思维</th></tr></thead><tbody><tr><td style="text-align:left;">时间单位</td><td style="text-align:left;">均等的30/31天</td><td style="text-align:left;">太阳运动的15°段</td></tr><tr><td style="text-align:left;">与自然的关系</td><td style="text-align:left;">人为规定，与自然无关</td><td style="text-align:left;">直接对应自然状态</td></tr><tr><td style="text-align:left;">季节感知</td><td style="text-align:left;">3月=春天（人为规定）</td><td style="text-align:left;">立春=春天开始（天文依据）</td></tr><tr><td style="text-align:left;">农业指导</td><td style="text-align:left;">无直接关联</td><td style="text-align:left;">直接指导农事操作</td></tr><tr><td style="text-align:left;">文化积累</td><td style="text-align:left;">约2000年历史</td><td style="text-align:left;">4000年以上历史</td></tr></tbody></table><p>节气思维，是一种与自然同频的时间感知方式。<br> 它不是&quot;落后&quot;，而是一种更贴近地球运动规律的时间观。</p><h2 id="九、承前启后" tabindex="-1">九、承前启后 <a class="header-anchor" href="#九、承前启后" aria-label="Permalink to &quot;九、承前启后&quot;">​</a></h2><p><strong>上承：</strong></p><ul><li>十二地支（地支月建 = 节气换月的容器）</li><li>六十甲子（干支纪年纪月，以节气为换月基准）</li><li>阴阳论（节气是阴阳消长的精确时间刻度）</li></ul><p><strong>本篇建立：</strong></p><ul><li>二十四节气 = 太阳历坐标系</li><li>节 vs 气的区别（术数换月的关键）</li><li>七十二候（节气的物候细化）</li><li>节气与各术数体系及中医的接口</li></ul><p><strong>下启：</strong></p><ul><li>→ 15·历法体系（节气是阴阳合历中&quot;阳&quot;的骨架，下篇系统讲历法）</li><li>→ 16·十二长生（节气月份与五行旺衰的精细化）</li><li>→ 17·五行旺相休囚死（节气季节与五行能量的对应）</li><li>→ 奇门遁甲实战（节气是奇门起局的时间基准）</li></ul><h2 id="十、本章小结" tabindex="-1">十、本章小结 <a class="header-anchor" href="#十、本章小结" aria-label="Permalink to &quot;十、本章小结&quot;">​</a></h2><p>二十四节气，是古人把太阳在黄道上运行一圈精确等分为二十四段的时间刻度系统。<br> 它不是农历的附属品，而是独立的太阳历坐标，是中华文明最重要的天文成就之一。</p><p><strong>五重价值：</strong></p><ol><li>🌞 <strong>天文价值：</strong> 精确的太阳历坐标系，误差在分钟级别，2000年前已完成</li><li>📅 <strong>历法价值：</strong> 阴阳合历中&quot;阳&quot;的骨架，是农历能够与太阳年同步的关键</li><li>🌾 <strong>农业价值：</strong> 古代农民的操作手册，指导播种、收割、储藏的全年节律</li><li>🔮 <strong>术数价值：</strong> 奇门·四柱·六爻·择日的时间基准，换月以节气为准</li><li>🎋 <strong>文化价值：</strong> 活在饮食、诗歌、民俗、中医中的时间智慧，2016年列入UNESCO非遗</li></ol><p><strong>学节气，有两个层次：</strong></p><p>第一层：记住二十四节气的名称、顺序、公历日期、对应地支月。这是工具层，必须熟练。</p><p>第二层：理解每个节气描述的那个自然状态——</p><blockquote><p>小寒是冬天最深处大雁调头的那一刻，<br> 立春是冻土里有什么东西悄悄醒来的那一刻，<br> 夏至是正午阳光直射头顶、影子消失的那一刻，<br> 冬至是家人围坐、庆祝白昼开始变长的那一刻……</p></blockquote><p><strong>第二层才是根。有了根，第一层自然记得住。</strong></p><p>节气不是日历上的标注，<br> 是天地在对你说：现在，是这个时候了。</p><hr><p><strong>下一篇预告：</strong></p><p>15 · 历法体系——阴历·阳历·阴阳合历，月建·朔望·闰月，<br> 以及为什么中国农历是世界上最复杂、也最精妙的历法体系。</p><hr><p><strong>文档版本：v1.1 · 二十四节气 | 2026年7月 | 已修订：四立括号补全·实例二补充·春分黄经注释·新增4.0七十二候·新增6.4中医接口·6.2气的奇门说明补充</strong></p>`,443)])])}const x=e(s,[["render",r]]);export{h as __pageData,x as default};
